import java.util.Scanner;

public class E {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int mod = 998244353;
        int n = scanner.nextInt();
        long K = scanner.nextLong();
        if (K >= n) {
            System.out.println(0);
            return;
        }
        int[][] factorials = computeFactorials(n, mod);
        if (K == 0) {
            System.out.println(factorials[0][n]);
            return;
        }
        long resultSum = 0;
        for (int i = (int) (n - K); i >= 1; i--) {
            int sign = ((n - K - i) % 2 == 0) ? 1 : -1;
            long comb = combination(n, i, mod, factorials);
            long powerVal = power(i, n, mod);
            long term = comb * powerVal % mod;
            term = term * sign % mod;
            long comb2 = combination((int) (n - i), (int) K, mod, factorials);
            resultSum = (resultSum + term * comb2) % mod;
        }
        resultSum = (resultSum * 2) % mod;
        System.out.println(resultSum);
    }

    public static long power(long base, int exp, int mod) {
        long res = 1;
        long b = base % mod;
        for (int i = 0; i < 64; i++) {
            if (((exp >> i) & 1) == 1) res = res * b % mod;
            b = b * b % mod;
        }
        return res;
    }

    public static long combination(int n, int r, int mod, int[][] factorials) {
        if (n < 0 || r < 0 || r > n) return 0;
        return (long) factorials[0][n] * factorials[1][r] % mod * factorials[1][n - r] % mod;
    }

    public static int[][] computeFactorials(int n, int mod) {
        int[] fact = new int[n + 1];
        int[] invFact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        long invNFact = power(fact[n], mod - 2, mod);
        invFact[n] = (int) invNFact;
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % mod);
        }
        return new int[][] { fact, invFact };
    }
}
